import ReactThreeTestRenderer from '@react-three/test-renderer'
import * as THREE from 'three'
import TerrainTile from '../src/TerrainTile.jsx'

async function renderTile(props) {
  const renderer = await ReactThreeTestRenderer.create(<TerrainTile {...props} />)
  const mesh = renderer.scene.findByName('tile')
  expect(mesh).toBeTruthy()
  return mesh.instance.geometry
}

describe('TerrainTile', () => {
  it('mounts with vertex grid of (16+1)^2 and heights within [-3, 3]', async () => {
    const geometry = await renderTile({ seed: 7, cells: 16, amplitude: 3 })
    expect(geometry.attributes.position.count).toBe((16 + 1) ** 2)
    for (let i = 0; i < geometry.attributes.position.count; i++) {
      const y = geometry.attributes.position.getY(i)
      expect(y).toBeGreaterThanOrEqual(-3)
      expect(y).toBeLessThanOrEqual(3)
    }
  })

  it('doubles amplitude: every y scales by exactly 2 within 1e-6', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <TerrainTile seed={7} cells={16} amplitude={3} />
    )
    const before = renderer.scene.findByName('tile').instance.geometry
    await renderer.update(<TerrainTile seed={7} cells={16} amplitude={6} />)
    const after = renderer.scene.findByName('tile').instance.geometry

    expect(before.attributes.position.count).toBe(after.attributes.position.count)
    for (let i = 0; i < after.attributes.position.count; i++) {
      const y0 = before.attributes.position.getY(i)
      const y1 = after.attributes.position.getY(i)
      expect(Math.abs(y1 - 2 * y0)).toBeLessThanOrEqual(1e-6)
    }
  })

  it('changing seed changes the height field', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <TerrainTile seed={7} cells={16} amplitude={3} />
    )
    const before = renderer.scene.findByName('tile').instance.geometry
    await renderer.update(<TerrainTile seed={8} cells={16} amplitude={3} />)
    const after = renderer.scene.findByName('tile').instance.geometry

    let differing = 0
    for (let i = 0; i < after.attributes.position.count; i++) {
      if (before.attributes.position.getY(i) !== after.attributes.position.getY(i)) {
        differing++
      }
    }
    expect(differing).toBeGreaterThan(0)
  })

  it('rerendering with identical props keeps the same geometry object', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <TerrainTile seed={7} cells={16} amplitude={3} />
    )
    const first = renderer.scene.findByName('tile').instance.geometry
    await renderer.update(<TerrainTile seed={7} cells={16} amplitude={3} />)
    const second = renderer.scene.findByName('tile').instance.geometry
    expect(second).toBe(first)
    expect(second).toBeInstanceOf(THREE.BufferGeometry)
  })
})
"})
