result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/TerrainTile.jsx", "content": "import React, { useMemo } from 'react'
import * as THREE from 'three'

/**
 * Inline seeded value-noise.
 *
 * Deterministic per (seed, x, z): the same seed always produces the same
 * height field, and the returned height is `noise * amplitude`, so scaling
 * `amplitude` scales every vertex's y by exactly the same factor.
 */
function makeHeightField(seed) {
  // 2D integer lattice hash -> [0, 1), fully determined by seed + coords.
  const hash = (ix, iz) => {
    let h = (ix * 374761393 + iz * 668265263 + seed * 1274126177) >>> 0
    h = ((h ^ (h >> 13)) * 1274126177) >>> 0
    h = (h ^ (h >> 16)) >>> 0
    return h / 4294967295
  }
  const smooth = (t) => t * t * (3 - 2 * t)
  // Bilinear interpolation of hashed lattice corners (value noise).
  const noise = (x, z) => {
    const ix = Math.floor(x)
    const iz = Math.floor(z)
    const fx = smooth(x - ix)
    const fz = smooth(z - iz)
    const n00 = hash(ix, iz)
    const n10 = hash(ix + 1, iz)
    const n01 = hash(ix, iz + 1)
    const n11 = hash(ix + 1, iz + 1)
    return (
      n00 * (1 - fx) * (1 - fz) +
      n10 * fx * (1 - fz) +
      n01 * (1 - fx) * fz +
      n11 * fx * fz
    )
  }
  return (x, z) => {
    // Two octaves over a normalized grid; result in [-1, 1].
    const base = noise(x / 8 + 100, z / 8 + 100) * 2 - 1
    const detail = (noise(x / 3.5 + 200, z / 3.5 + 200) * 2 - 1) * 0.35
    return THREE.MathUtils.clamp((base + detail) / 1.35, -1, 1)
  }
}

export default function TerrainTile({ seed = 0, cells = 16, amplitude = 1 }) {
  // Geometry is rebuilt whenever any prop changes; identical props reuse it.
  const geometry = useMemo(() => {
    const geo = new THREE.PlaneGeometry(cells, cells, cells, cells)
    const heightAt = makeHeightField(seed)
    const pos = geo.attributes.position
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i)
      const z = pos.getY(i) // PlaneGeometry lies in XY before rotation
      pos.setZ(i, heightAt(x, z))
    }
    pos.needsUpdate = true
    geo.computeVertexNormals()
    geo.rotateX(-Math.PI / 2) // lay flat: displaced axis becomes y
    return geo
  }, [seed, cells, amplitude])

  return <mesh name="tile" geometry={geometry}>
    <meshStandardMaterial color="#7aa05a" flatShading />
  </mesh>
}
